// ../app/dist/cli/services/webhook/request-api-versions.js
init_cjs_shims();
var GetApiVersionsQuery = `
  query getApiVersions {
    publicApiVersions
  }
`;
async function requestApiVersions(developerPlatformClient, organizationId) {
  let { publicApiVersions: result } = await developerPlatformClient.apiVersions(organizationId), unstableIdx = result.indexOf("unstable");
  return unstableIdx === -1 ? result.sort().reverse() : (result.splice(unstableIdx, 1), result.sort().reverse(), result.push("unstable")), result;
}

